#!/usr/bin/env python3
"""Byte-exact reference model for `seqtk subseq` (v1.5-r133)."""
import sys

INT64_MAX = (1 << 63) - 1
SPACE = frozenset(b' \t\n\v\f\r')          # C isspace() in the "C" locale
NL = 0x0a

# ---------- complement table (256 bytes) -------------------------------------
def _mk_comp():
    t = bytearray(range(256))
    pairs = {'A':'T','B':'V','C':'G','D':'H','G':'C','H':'D','K':'M','M':'K',
             'R':'Y','T':'A','U':'A','V':'B','Y':'R'}
    for k, v in pairs.items():
        t[ord(k)] = ord(v); t[ord(k.lower())] = ord(v.lower())
    t[ord('`')] = ord('@')                  # quirk of seqtk's comp_tab
    for c in range(128, 256):
        t[c] = ord('N')
    return bytes(t)
COMP = _mk_comp()

def revcomp(s: bytes) -> bytes:
    return bytes(COMP[c] for c in reversed(s))

# ---------- kseq-like FASTA/FASTQ reader -------------------------------------
def kseq_read(data: bytes):
    """Yield (name, comment, seq, qual). Mirrors kseq_read()."""
    i, n = 0, len(data)
    while True:
        while i < n and data[i] not in (0x3e, 0x40):      # '>' '@'
            i += 1
        if i >= n:
            return
        i += 1
        # ---- header ----
        j = i
        while j < n and data[j] not in SPACE:
            j += 1
        name = data[i:j]
        comment = b''
        if j < n and data[j] != NL:
            k = data.index(NL, j) if NL in data[j:] else n
            comment = data[j + 1:k]
            j = k
        i = j + 1 if j < n else n
        # ---- sequence ----
        seq = bytearray(); qual = bytearray(); saw_plus = False
        while i < n:
            e = data.index(NL, i) if NL in data[i:] else n
            line = data[i:e]
            if line.endswith(b'\r'):
                line = line[:-1]
            if len(line) == 0:
                i = e + 1
                continue
            if line[0] in (0x3e, 0x40, 0x2b):             # '>' '@' '+'
                if line[0] == 0x2b:
                    saw_plus = True
                    i = e + 1
                break
            seq += line
            i = e + 1
        if saw_plus:
            while i < n and len(qual) < len(seq):
                e = data.index(NL, i) if NL in data[i:] else n
                line = data[i:e]
                if line.endswith(b'\r'):
                    line = line[:-1]
                i = e + 1
                if len(line) == 0:
                    continue
                qual += line
            if len(qual) != len(seq):
                return                                     # discard + stop
            yield bytes(name), bytes(comment), bytes(seq), bytes(qual)
        else:
            yield bytes(name), bytes(comment), bytes(seq), b''

# ---------- region / name-list reader ---------------------------------------
def _getuntil(data, i):
    """kseq ks_getuntil(KS_SEP_SPACE). Returns (field, dret, new_i, ret)."""
    n = len(data)
    if i >= n:
        return b'', 0, i, -1                 # EOF, nothing read
    j = i
    while j < n and data[j] not in SPACE:
        j += 1
    if j < n:
        return data[i:j], data[j], j + 1, j - i
    return data[i:j], 0, j, j - i            # terminated by EOF

def _strtol(b: bytes) -> int:
    k = 0
    while k < len(b) and 0x30 <= b[k] <= 0x39:
        k += 1
    if k == 0:
        return 0
    return min(int(b[:k]), INT64_MAX)

def read_regions(data: bytes):
    """dict name -> list of (beg, end, rev), in file order."""
    reg = {}
    i = 0
    while True:
        name, dret, i, ret = _getuntil(data, i)
        if ret < 0:
            break
        beg = end = -1
        rev = False
        if dret != NL:
            f2, dret, i, r2 = _getuntil(data, i)
            if r2 > 0 and 0x30 <= f2[0] <= 0x39:
                beg = _strtol(f2)
            if dret != NL:
                f3, dret, i, r3 = _getuntil(data, i)
                if r3 > 0 and 0x30 <= f3[0] <= 0x39:
                    end = _strtol(f3)
                if dret != NL:
                    _f4, dret, i, _r4 = _getuntil(data, i)
                    if dret != NL:
                        _f5, dret, i, _r5 = _getuntil(data, i)
                        if dret != NL:
                            f6, dret, i, r6 = _getuntil(data, i)
                            if r6 > 0 and f6[0] == 0x2d:   # '-'
                                rev = True
        if dret != NL:                        # discard rest of the line
            n = len(data)
            while i < n:
                c = data[i]; i += 1
                if c == NL:
                    break
        if end < 0 and beg > 0:
            end, beg = beg, beg - 1
        if beg < 0:
            beg, end = 0, INT64_MAX
        reg.setdefault(name, []).append((beg, end, rev))
    return reg

# ---------- main ------------------------------------------------------------
def subseq(fa: bytes, lst: bytes, tab=False, strand=False, line_len=0):
    out = bytearray(); err = bytearray()
    reg = read_regions(lst)
    for name, comment, seq, qual in kseq_read(fa):
        if name not in reg:
            continue
        L = len(seq)
        for beg, end, rev in reg[name]:
            if beg >= L:
                err += b'[subseq] %s: %d >= %d\n' % (name, beg, L)
                continue
            e = L if (end > L or end < 0) else end
            if tab:
                head = b'%s\t%d\t' % (name, beg + 1)
            else:
                head = (b'@' if qual else b'>') + name
                if beg > 0 or end != INT64_MAX:
                    head += b':%d-%d' % (beg + 1, e)
                if comment:
                    head += b' ' + comment
            if strand:
                if e < beg:
                    continue
                sl = seq[beg:e]
                if rev:
                    sl = revcomp(sl)
                out += head + b'\n' + sl + b'\n'
            elif tab:
                out += head + seq[beg:e] + b'\n'
            else:
                out += head
                out += _fold(seq[beg:e], line_len)
                if qual:
                    out += b'\n+' + _fold(qual[beg:e], line_len)
                out += b'\n'
    return bytes(out), bytes(err)

def _fold(s: bytes, l: int) -> bytes:
    o = bytearray()
    for j, ch in enumerate(s):
        if j == 0 or (l > 0 and j % l == 0):
            o += b'\n'
        o.append(ch)
    return bytes(o)

if __name__ == '__main__':
    import argparse
    ap = argparse.ArgumentParser(add_help=False)
    ap.add_argument('-t', action='store_true')
    ap.add_argument('-s', action='store_true')
    ap.add_argument('-l', type=int, default=0)
    ap.add_argument('fa'); ap.add_argument('lst')
    a = ap.parse_args()
    o, e = subseq(open(a.fa, 'rb').read(), open(a.lst, 'rb').read(),
                  a.t, a.s, a.l)
    sys.stdout.buffer.write(o); sys.stderr.buffer.write(e)
PYEOF
